import request from './request'

// 帖子相关API
export const postAPI = {
  // 获取帖子列表
  getPostList: (params) => request.get('/api/community/posts', { params }),
  // 获取帖子详情
  getPostDetail: (id) => request.get(`/api/community/posts/${id}`),
  // 发布帖子
  createPost: (data) => request.post('/api/community/posts', data),
  // 更新帖子
  updatePost: (id, data) => request.put(`/api/community/posts/${id}`, data),
  // 删除帖子
  deletePost: (id) => request.delete(`/api/community/posts/${id}`),
  // 设置最佳答案
  setBestAnswer: (id, commentId) => request.put(`/api/community/posts/${id}/best-answer`, { commentId })
}

// 评论相关API
export const commentAPI = {
  // 获取帖子评论列表
  getCommentsByPostId: (postId, params) => request.get(`/api/community/comments/post/${postId}`, { params }),
  // 获取评论的回复列表
  getRepliesByCommentId: (commentId) => request.get(`/api/community/comments/${commentId}/replies`),
  // 发布评论
  createComment: (data) => request.post('/api/community/comments', data),
  // 更新评论
  updateComment: (id, data) => request.put(`/api/community/comments/${id}`, data),
  // 删除评论
  deleteComment: (id) => request.delete(`/api/community/comments/${id}`)
}

// 点赞相关API
export const likeAPI = {
  // 检查是否已点赞
  checkLike: (targetId, targetType) => request.get('/api/community/likes/check', { params: { targetId, targetType } }),
  // 切换点赞状态
  toggleLike: (targetId, targetType) => request.post('/api/community/likes/toggle', { targetId, targetType })
}

// 关注相关API
export const followAPI = {
  // 检查是否已关注
  checkFollow: (followUserId) => request.get('/api/community/follows/check', { params: { followUserId } }),
  // 切换关注状态
  toggleFollow: (followUserId) => request.post('/api/community/follows/toggle', { followUserId }),
  // 获取用户关注数
  getFollowCount: (userId) => request.get(`/api/community/follows/count/following/${userId}`),
  // 获取用户粉丝数
  getFollowerCount: (userId) => request.get(`/api/community/follows/count/followers/${userId}`)
}
